import{_ as t,c as s,o as i,ag as a}from"./chunks/framework.CB_NIqHd.js";const u=JSON.parse('{"title":"Are you using any tool to enforce it, is it included in hooks as well?","description":"","frontmatter":{},"headers":[],"relativePath":"senior_growth/Clean_code_and_Code_Quality/Are_you_using_any_tool_to_enforce_it,_is_it_included_in_hooks_as_well.md","filePath":"senior_growth/Clean_code_and_Code_Quality/Are_you_using_any_tool_to_enforce_it,_is_it_included_in_hooks_as_well.md"}'),o={name:"senior_growth/Clean_code_and_Code_Quality/Are_you_using_any_tool_to_enforce_it,_is_it_included_in_hooks_as_well.md"};function n(l,e,r,h,c,d){return i(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="are-you-using-any-tool-to-enforce-it-is-it-included-in-hooks-as-well" tabindex="-1">Are you using any tool to enforce it, is it included in hooks as well? <a class="header-anchor" href="#are-you-using-any-tool-to-enforce-it-is-it-included-in-hooks-as-well" aria-label="Permalink to “Are you using any tool to enforce it, is it included in hooks as well?”">​</a></h1><h2 id="🛠-tools-to-enforce-code-quality-hooks-integration" tabindex="-1">🛠 Tools to Enforce Code Quality &amp; Hooks Integration <a class="header-anchor" href="#🛠-tools-to-enforce-code-quality-hooks-integration" aria-label="Permalink to “🛠 Tools to Enforce Code Quality &amp; Hooks Integration”">​</a></h2><h3 id="hooks" tabindex="-1">Hooks <a class="header-anchor" href="#hooks" aria-label="Permalink to “Hooks”">​</a></h3><p>In React, <strong>hooks</strong> are special functions that let you use state and other React features in functional components.</p><ul><li><p><strong>useState:</strong> The useState hook lets you add local state to functional components in React. It provides a stateful value and a function to update it, preserving the state across re-renders. When you call setState, the component does not update immediately. Instead, React schedules a re-render, and the new state will be available on the next render.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">setCount</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> useState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p><code>count</code> is the state variable, and <code>setCount</code> updates it.</p></li><li><p><strong>useEffect:</strong> Runs side effects (like data fetching or DOM manipulation) after rendering. Combines lifecycle methods from class components.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">useEffect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  document.title </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `You clicked ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">count</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">} times`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}, [count]);</span></span></code></pre></div><p>The <code>[count]</code> dependency ensures the effect runs only when <code>count</code> changes.</p></li><li><p><strong>useContext:</strong> Shares data globally without passing props manually. React&#39;s Context API provides a way to pass data through the component tree without having to manually pass props down at every level. The useContext hook is the idiomatic way to consume context values in functional components.</p></li></ul><p>✅ What useContext Does<br> The useContext hook allows a component to read the current value of a context. It takes a context object (the one returned from React.createContext) as an argument and returns the current context value.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> value</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> useContext</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(MyContext);</span></span></code></pre></div><ul><li><p><strong>useReducer:</strong> Groups related transitions into a pure reducer when named actions/invariants are clearer than separate setters. It is not generally discouraged. State still belongs to the component invoking the hook, and a provider can share that state/dispatch through Context. It does not supply Redux&#39;s store/selectors/middleware automatically. See the <a href="./../React/What_Are_React_Hooks_Good_For_Rules_of_Hooks.html#refs-pure-reducers-scoped-context-and-custom-hooks">scoped reducer lesson</a>.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">state</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">dispatch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> useReducer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(reducer, initialState);</span></span></code></pre></div></li><li><p><strong>useRef:</strong> Creates a mutable object that persists across renders, often used to access DOM elements.</p></li></ul><p>There are two common use cases for useRef:</p><ul><li><p>Accessing a DOM element directly</p></li><li><p>Storing mutable values that don’t require triggering a component update</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> inputRef</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> useRef</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div></li><li><p><strong>useCallback, useMemo:</strong><br> Both represent a possibility to create memoized values of some internally used values (useMemo) and callbacks (useCallback).</p></li></ul><p>useCallback could be implemented via useMemo, so it’s basically a shortcut. In most cases used for passing callbacks as props to underlying components in order to prevent them from unnecessary re-rendering all the time.</p><p>useMemo is typically used to avoid unnecessary re-calculations on render phase.</p><ul><li><strong>Custom Hooks:</strong> Combine built-in hooks to create reusable logic across components.</li></ul><h4 id="custom-hooks" tabindex="-1">Custom Hooks <a class="header-anchor" href="#custom-hooks" aria-label="Permalink to “Custom Hooks”">​</a></h4><p>Custom hooks are one of the most powerful concepts in React, enabling developers to separate and reuse logic efficiently. They are simply JavaScript functions, but when they use React’s built-in hooks like <code>useState</code>, <code>useEffect</code>, or <code>useContext</code>, they unlock the ability to encapsulate complex behaviors in an easily reusable and shareable way.</p><blockquote><p><strong>Rule:</strong><br> Custom hooks must be called exclusively inside React components or other hooks. This ensures React&#39;s hook rules are followed.</p></blockquote><p><strong>Benefits of Custom Hooks:</strong></p><ul><li><strong>Cleaner Code:</strong> Move logic out of components to keep them focused and tidy.</li><li><strong>Abstraction:</strong> Hide complex logic behind a simple and reusable interface.</li><li><strong>Reusability:</strong> Share logic across multiple components without duplicating code.</li><li><strong>Consistency:</strong> Standardize coding practices for state management, API calls, or side effects.</li><li><strong>Enhanced Development:</strong> Encourages modular and fun coding practices.</li></ul><h3 id="key-points" tabindex="-1">Key Points <a class="header-anchor" href="#key-points" aria-label="Permalink to “Key Points”">​</a></h3><ul><li><strong>Custom hooks must follow React&#39;s rules of hooks:</strong><ul><li>Only call hooks at the top level.</li><li>Only call hooks from React functions (components or other hooks).</li><li>Hook names always start with <code>use</code>.</li></ul></li><li>They allow developers to encapsulate any logic, making applications more modular and maintainable.</li><li>With custom hooks, you can significantly enhance your development process, making code cleaner, reusable, and more efficient.</li></ul><p>In modern JavaScript/TypeScript projects, enforcing code quality is <strong>automated using various tools</strong>, often integrated with <strong>pre-commit hooks, CI/CD pipelines, and IDEs</strong>. These tools provide feedback on configured checks; they cannot establish overall correctness. React hooks above and Git lifecycle hooks below are different concepts.</p><hr><h2 id="_1️⃣-common-tools" tabindex="-1">1️⃣ Common Tools <a class="header-anchor" href="#_1️⃣-common-tools" aria-label="Permalink to “1️⃣ Common Tools”">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th><th>Notes</th></tr></thead><tbody><tr><td><strong>ESLint</strong></td><td>Linting for JavaScript/TypeScript</td><td>Finds errors, enforces style, supports custom rules</td></tr><tr><td><strong>Prettier</strong></td><td>Code formatting</td><td>Ensures consistent style, works with ESLint</td></tr><tr><td><strong>Stylelint</strong></td><td>Linting for CSS/SCSS/styled-components</td><td>Enforces UI style consistency</td></tr><tr><td><strong>Husky</strong></td><td>Git hooks management</td><td>Runs scripts on <code>pre-commit</code>, <code>pre-push</code>, etc.</td></tr><tr><td><strong>lint-staged</strong></td><td>Lint staged files only</td><td>Improves hook speed, checks only changed files</td></tr><tr><td><strong>SonarQube/SonarCloud</strong></td><td>Static analysis, code smells, security</td><td>Typically runs in CI/CD pipelines</td></tr><tr><td><strong>Jest/Vitest</strong></td><td>Unit testing and coverage</td><td>Can block commits if tests fail</td></tr></tbody></table><hr><h2 id="_2️⃣-integration-with-hooks" tabindex="-1">2️⃣ Integration with Hooks <a class="header-anchor" href="#_2️⃣-integration-with-hooks" aria-label="Permalink to “2️⃣ Integration with Hooks”">​</a></h2><p><strong>Pre-commit hooks</strong> run local feedback checks before a normal commit; they can be bypassed:</p><p><strong>Current Husky setup in an independent practice repository:</strong> install a compatible pinned Husky release as a dev dependency, then run npx husky init. Review the generated prepare script and .husky/pre-commit. Keep existing lifecycle scripts when integrating; do not overwrite a submission template. The old package.json husky.hooks object is a legacy configuration and is not the current setup.</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># .husky/pre-commit — after the installed Husky version initializes its hook runner</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span></span></code></pre></div><p>A lint-staged alternative installs/configures that tool explicitly and invokes its local binary from the hook; commands receive staged filenames. Avoid hand-built shell filename splitting. Fixers can change partially staged working files, so test the selected tool&#39;s staging behavior. This primary example uses the full small lint target, not a pretend staged-only command.</p><ul><li><strong>Behavior:</strong><ul><li>When committing code, The hook above runs the configured full lint target; lint-staged is a separately configured alternative.</li><li>Failing linting prevents the commit.</li></ul></li></ul><p><strong>Optional:</strong> Pre-push hooks can also run:</p><ul><li>Unit tests</li><li>Type checking (<code>tsc --noEmit</code>)</li><li>Security scans</li></ul><hr><h2 id="_3️⃣-ci-cd-enforcement" tabindex="-1">3️⃣ CI/CD Enforcement <a class="header-anchor" href="#_3️⃣-ci-cd-enforcement" aria-label="Permalink to “3️⃣ CI/CD Enforcement”">​</a></h2><p>Even with hooks, <strong>CI/CD pipelines</strong> rerun checks independently of local hooks:</p><ul><li>Runs full linting, formatting, unit tests, coverage, and security checks</li><li>Prevents merging code that passes local hooks but fails global rules</li><li>Common platforms: GitHub Actions, GitLab CI/CD, Jenkins, CircleCI</li></ul><hr><h2 id="_4️⃣-benefits-of-hook-tool-integration" tabindex="-1">4️⃣ Benefits of Hook + Tool Integration <a class="header-anchor" href="#_4️⃣-benefits-of-hook-tool-integration" aria-label="Permalink to “4️⃣ Benefits of Hook + Tool Integration”">​</a></h2><ol><li><strong>Immediate feedback:</strong> Developers fix issues before committing.</li><li><strong>Consistency across the team:</strong> All developers follow the same rules automatically.</li><li><strong>Reduced technical debt:</strong> Enforces standards from day one.</li><li><strong>Improved code review efficiency:</strong> Code arrives cleaner for review.</li></ol><hr><h3 id="✅-key-takeaways" tabindex="-1">✅ Key Takeaways <a class="header-anchor" href="#✅-key-takeaways" aria-label="Permalink to “✅ Key Takeaways”">​</a></h3><ul><li>Tools like <strong>ESLint, Prettier, Stylelint, Jest, SonarQube</strong> are essential for code quality.</li><li><strong>Hooks (pre-commit, pre-push)</strong> enforce standards <strong>locally before code leaves the developer’s machine</strong>.</li><li>Combined with required CI checks, this improves feedback and enforces the selected rules; review and behavior testing remain necessary.</li></ul><blockquote><p>💡 Senior Tip:<br> Always use <strong>hooks for developer productivity</strong> and <strong>CI/CD for enforcement at the team level</strong>. Local hooks catch issues early, protected CI checks enforce configured gates; untested behavior and misconfiguration can still slip through.</p></blockquote><h2 id="verify-enforcement-without-touching-the-submission-template" tabindex="-1">Verify enforcement without touching the submission template <a class="header-anchor" href="#verify-enforcement-without-touching-the-submission-template" aria-label="Permalink to “Verify enforcement without touching the submission template”">​</a></h2><p>Use the <a href="./What_is_code_standard_What_code_standard_is_on_your_current_project_Should_we_always_work_by_code_standard_Have_you_used_linters_and_do_you_have_any_experience_in_configuring_them.html#minimal-executable-standard">minimal lint/type/test/build lab</a>. Test a passing source, an ESLint violation and a type error; the gate must stop with a nonzero exit. A hook is developer convenience, not a security boundary: HUSKY=0 or Git options can bypass it. Required CI/status checks and repository policy are separate administrative configuration, not implemented by this document. No push is part of this exercise; only the user may push.</p><p><strong>Acceptance:</strong> explain React versus Git hooks, reducer/Context ownership, initialized .husky files and bypass behavior. In an isolated Git practice checkout, install the pinned compatible hook release, inspect the generated runner and demonstrate both an allowed and blocked local commit without changing src/tests. Hook installation/commit behavior itself remains learner practice here; the gate commands are checked separately.</p><p>References checked2026-10-24: <a href="https://typicode.github.io/husky/get-started.html" target="_blank" rel="noreferrer">Husky current initialization</a>, <a href="https://react.dev/reference/react/useReducer" target="_blank" rel="noreferrer">React useReducer</a>, <a href="https://react.dev/learn/scaling-up-with-reducer-and-context" target="_blank" rel="noreferrer">React reducer and Context</a>.</p>',48)])])}const k=t(o,[["render",n]]);export{u as __pageData,k as default};
